'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
const {chromium}=require('playwright');
const site=path.resolve(__dirname,'../..'),html=fs.readFileSync(path.join(site,'index.html'),'utf8');
const css=[...html.matchAll(/<style[^>]*>([\s\S]*?)<\/style>/gi)].map(m=>m[1]).join('\n');
const source=html.slice(html.indexOf('function normalizePcRuleData('),html.indexOf('function normalizePcArchive('))+'\n'+html.slice(html.indexOf('function pcGenericRuleEditorHTML('),html.indexOf('function pcProfileEditorHTML('));
const fixture=`<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>${css}</style><div id="host" style="margin:auto;max-width:min(100%,780px);padding:12px;overflow:hidden;background:#fff"></div>`;
const setup=`function clone(x){return JSON.parse(JSON.stringify(x));}function moduleRuleDisplay(meta){return meta.systemId||'规则';}function escapeHTML(s){return String(s??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]||c));}\n${source}\nconst pc={ruleMeta:{familyId:'saikoro-fiction',systemId:'insane',editionId:''},ruleData:{traits:[{label:'旧资料',value:'重要旧值'}],skills:[],resources:[]},ruleSheets:{},coc:{hp:12,san:60},excelEdits:[{value:'原Excel'}]};pcRuleEditableData(pc).traits[0].value='6';document.getElementById('host').innerHTML=pcGenericRuleEditorHTML(pc);window.probe={pc,current:pcRuleCurrentData(pc)};`;
(async()=>{const browser=await chromium.launch({headless:true,args:['--no-sandbox'],...(process.env.PL_CI_CHROMIUM_EXECUTABLE?{executablePath:process.env.PL_CI_CHROMIUM_EXECUTABLE}:{})});try{for(const [width,height] of [[1440,900],[390,844],[320,680]]){const page=await browser.newPage({viewport:{width,height}});const errors=[];page.on('pageerror',e=>errors.push(String(e)));try{await page.setContent(fixture);await page.evaluate(`(()=>{${setup}})()`);const result=await page.evaluate(()=>({overflow:document.documentElement.scrollWidth-innerWidth,rows:document.querySelectorAll('.pc-generic-rule-row').length,controls:[...document.querySelectorAll('[data-pc-generic-add]')].map(x=>Math.round(x.getBoundingClientRect().height)),legacy:!!document.querySelector('[data-pc-copy-legacy-rule]'),value:document.querySelector('[data-pc-generic-field="value"]').value,oldData:window.probe.pc.ruleData.traits[0].value,coc:window.probe.pc.coc.hp}));assert.deepEqual(errors,[]);assert(result.overflow<=1,`${width}px overflow ${JSON.stringify(result)}`);assert(result.rows>=2&&result.legacy&&result.value==='6'&&result.oldData==='重要旧值'&&result.coc===12);assert(result.controls.every(n=>n>=42),`${width}px controls too small ${JSON.stringify(result)}`);console.log(`round148 ${width}x${height}: template/legacy/42px controls/no overflow PASS`);}catch(err){const dir=process.env.PL_SYNTHETIC_REPORT_DIR;if(dir){fs.mkdirSync(dir,{recursive:true});await page.screenshot({path:path.join(dir,`round148-${width}x${height}-failure.png`)});}throw err;}finally{await page.close();}}}finally{await browser.close();}})().catch(err=>{console.error(err.stack||err);process.exitCode=1});
